        bad = [("S", 2025, 1), ("SLSXX", 2025, 1), ("sls", 2025, 1), ("S1S", 2025, 1), ("", 2025, 1), ("SLS", 1999, 1),
               ("SLS", 2100, 1), ("SLS", 2025, 0), ("SLS", 2025, 1_000_000), ("SLS", 2025, -4), ("SIS", 2025, 1)]
        for args in bad:
            with self.assertRaises(ValueError, msg=args):
                make_number(*args)

