        # per line: 33 * 5% = 1.65 -> 2 each (6 in total); on the invoice: 99 * 5% = 4.95 -> 5
        got = tax_split([33, 33, 33], 500)
        self.assertEqual(sum(t for _, t, _ in got), 5)
